<template>
 <section aria-label="业务原执行的明确物理映射">
  <p>业务原执行 {{legacyScheduleId}}。请核对参与位置、人员资质和资源池。</p>
  <p v-if="error" role="alert">{{error}}</p>
  <el-form label-position="top">
   <el-form-item label="原执行参与位置"><el-select v-model="participant" aria-label="原执行参与位置" :disabled="loading"><el-option v-for="(label,key) in participants" :key="key" :value="key" :label="label"/></el-select></el-form-item>
   <el-form-item label="明确映射的物理资源"><el-select v-model="resourceId" aria-label="明确映射的物理资源" :disabled="loading||!participant"><el-option v-for="row in candidateResources" :key="row.resource_id" :value="row.resource_id" :label="row.resource_kind+' · '+row.resource_id"/></el-select></el-form-item>
   <p v-if="resource">已核对物理原件：{{resource.payload.label}} · {{resource.resource_id}}。原件SHA {{resource.content_hash}}。</p>
   <template v-if="participant==='room'&&resource">
    <el-form-item label="本条原执行专属房间映射"><el-select v-model="aliasId" aria-label="本条原执行专属房间映射" :disabled="loading"><el-option v-for="row in candidateAliases" :key="row.alias_id" :value="row.alias_id" :label="'本条原执行映射 · '+row.alias_id"/></el-select></el-form-item>
    <p v-if="alias">已核对原房间文字（保留全部空白）：{{JSON.stringify(alias.payload.raw_original_text)}}。本条映射独立发布，命名空间别名不能代替。</p>
    <p v-if="!candidateAliases.length">尚无本条原执行专属且已发布的房间映射，请先在资源登记页明确建立并审核。</p>
   </template>
   <template v-if="participant&&participant!=='room'&&resource">
    <p v-if="account">已核对该自然人的永久实际账号 #{{account.user_id}}；关联原件 {{account.binding_id}}。</p><p v-else>所选自然人尚无可核对的永久账号关联，不能登记保护忙时。</p>
    <el-checkbox v-if="account" v-model="accountReviewed">已明确审阅：所选实际账号、自然人与本条原执行的参与位置相同，提交后仍由服务器核对原人员。</el-checkbox>
    <el-form-item v-if="participant==='assistant'" label="本条原助手的实际医师别名"><el-select v-model="assistantId" aria-label="本条原助手的实际医师别名" :disabled="loading"><el-option v-for="row in doctors" :key="row.doctor_id" :value="row.doctor_id" :label="row.name+' · #'+row.doctor_id"/></el-select></el-form-item>
   </template>
  </el-form>
  <ProtectedEditor v-if="binding" :pool-id="poolId" :binding="binding" @validity="report"/>
 </section>
</template>
<script setup>
import {computed,onActivated,onBeforeUnmount,onDeactivated,ref,watch} from 'vue';
import {useStore} from 'vuex';
import {supportId} from '@/api/inpatientSupport';
import {getCompleteSurgeryRegistry,getSurgeryRegistryRecord,getSurgeryDoctorIdentities,verifySurgeryRegistry} from '@/api/ai/surgerySources';
import ProtectedEditor from './ProtectedEditor.vue';
const props=defineProps({poolId:{type:String,required:true},legacyScheduleId:{type:String,required:true}}),emit=defineEmits(['validity','invalidate']),store=useStore();
const participants={room:'原手术室',surgeon:'原术者',anesthesia:'原麻醉',assistant:'原助手',scrub_nurse:'原器械护士',circulating_nurse:'原巡回护士'},participant=ref(null),resourceId=ref(null),aliasId=ref(null),assistantId=ref(null),resources=ref([]),memberships=ref([]),aliases=ref([]),accounts=ref([]),doctors=ref([]),resource=ref(null),alias=ref(null),account=ref(null),accountReviewed=ref(false),error=ref(''),loading=ref(false);let epoch=0,alive=true,wasDeactivated=false;
const roles=computed(()=>store.getters['user/permissions']||[]),allowed=computed(()=>!!store.state.user.accessToken&&roles.value.includes('super_admin')&&supportId(props.poolId)&&supportId(props.legacyScheduleId));
const candidateResources=computed(()=>resources.value.filter(r=>r.resource_kind===(participant.value==='room'?'room':'person'))),candidateAliases=computed(()=>aliases.value.filter(r=>r.resource_id===resourceId.value&&r.alias_scope==='legacy_schedule'&&r.legacy_schedule_id===props.legacyScheduleId));
const binding=computed(()=>allowed.value&&resource.value&&resource.value.resource_id===resourceId.value&&Object.hasOwn(participants,participant.value)&&(participant.value==='room'?alias.value&&alias.value.alias_id===aliasId.value:account.value&&accountReviewed.value)&&(participant.value!=='assistant'||doctors.value.some(d=>d.doctor_id===assistantId.value))?{legacy_schedule_id:props.legacyScheduleId,resource_id:resourceId.value,participant_kind:participant.value,room_alias_id:participant.value==='room'?aliasId.value:null,assistant_doctor_id:participant.value==='assistant'?assistantId.value:null}:null);
function boundary(){return JSON.stringify([store.state.user.accessToken,roles.value,props.poolId,props.legacyScheduleId,participant.value,resourceId.value,aliasId.value]);}function ticket(){return{epoch:++epoch,boundary:boundary()};}function current(t){return alive&&allowed.value&&t.epoch===epoch&&t.boundary===boundary();}
function report(value){const b=binding.value;emit('validity',b&&value?.valid&&value.request?.pool_id===props.poolId&&Object.entries(b).every(([key,item])=>value.request[key]===item)?value:{valid:false,request:null});}
function invalidate(){epoch++;loading.value=false;error.value='';resource.value=null;alias.value=null;account.value=null;accountReviewed.value=false;assistantId.value=null;emit('validity',{valid:false,request:null});}
function clear(){invalidate();resources.value=[];memberships.value=[];aliases.value=[];accounts.value=[];doctors.value=[];}
function failed(t,e){if(!current(t))return;clear();error.value=e?.message||'当前原执行映射目录或实际身份不可核对';emit('invalidate');}
async function initialize(){clear();if(!allowed.value)return;const t=ticket();loading.value=true;try{const [r,a,p,m]=await Promise.all(['resource','room_alias','person_account','pool_membership'].map(kind=>getCompleteSurgeryRegistry(kind,{pool_id:props.poolId})));if(!current(t))return;memberships.value=m.filter(v=>v.eligible_for_new_use&&v.governance?.status==='published'&&v.pool_id===props.poolId);resources.value=r.filter(v=>v.eligible_for_new_use&&['room','person'].includes(v.resource_kind)&&memberships.value.some(x=>x.resource_id===v.resource_id));aliases.value=a.filter(v=>v.eligible_for_new_use&&v.governance?.status==='published');accounts.value=p.filter(v=>v.eligible_for_new_use);}catch(e){failed(t,e);}finally{if(current(t))loading.value=false;}}
async function inspectResource(){invalidate();if(!allowed.value||!resourceId.value||!participant.value)return;const meta=candidateResources.value.find(r=>r.resource_id===resourceId.value);if(!meta){error.value='该资源不属于当前明确参与位置的物理类型';return;}const t=ticket();loading.value=true;try{const row=(await getSurgeryRegistryRecord('resource',resourceId.value,{pool_id:props.poolId})).data;if(!current(t))return;if(row?.content_hash!==meta.content_hash||!row.eligible_for_new_use||!await verifySurgeryRegistry(row,'resource',{auditOnly:true}))throw new Error('所选物理资源完整原件与当前目录不一致');const members=memberships.value.filter(v=>v.resource_id===row.resource_id);if(members.length!==1)throw new Error('物理资源必须具有当前资源池唯一的已发布成员声明');const member=(await getSurgeryRegistryRecord('pool_membership',members[0].membership_id,{pool_id:props.poolId})).data;if(!current(t))return;if(member?.content_hash!==members[0].content_hash||member.governance_hash!==members[0].governance_hash||member.resource_id!==row.resource_id||member.pool_id!==props.poolId||!member.eligible_for_new_use||member.governance?.status!=='published'||!await verifySurgeryRegistry(member,'pool_membership',{auditOnly:true}))throw new Error('物理资源的完整成员声明与当前资源池不符');let person=null,identities=[];if(participant.value!=='room'){const matches=accounts.value.filter(r=>r.resource_id===resourceId.value);if(matches.length!==1)throw new Error('自然人必须具有唯一完整永久账号关联，不能猜配');person=(await getSurgeryRegistryRecord('person_account',matches[0].binding_id,{pool_id:props.poolId})).data;if(!current(t))return;if(person?.content_hash!==matches[0].content_hash||person.resource_id!==row.resource_id||!person.eligible_for_new_use||!await verifySurgeryRegistry(person,'person_account',{auditOnly:true}))throw new Error('自然人账号完整原件与所选物理资源不一致');if(participant.value==='assistant')identities=await getSurgeryDoctorIdentities();}if(!current(t))return;resource.value=row;account.value=person;doctors.value=identities;}catch(e){failed(t,e);}finally{if(current(t))loading.value=false;}}
async function inspectAlias(){alias.value=null;emit('validity',{valid:false,request:null});if(!allowed.value||participant.value!=='room'||!aliasId.value)return;const meta=candidateAliases.value.find(a=>a.alias_id===aliasId.value);if(!meta){error.value='所选房间映射与本条执行记录不匹配';return;}const t=ticket();loading.value=true;try{const row=(await getSurgeryRegistryRecord('room_alias',aliasId.value,{pool_id:props.poolId})).data;if(!current(t))return;if(row?.content_hash!==meta.content_hash||row.resource_id!==resourceId.value||row.alias_scope!=='legacy_schedule'||row.legacy_schedule_id!==props.legacyScheduleId||row.governance?.status!=='published'||!row.eligible_for_new_use||!await verifySurgeryRegistry(row,'room_alias',{auditOnly:true}))throw new Error('原执行专属房间映射、治理或当前原件不一致');if(current(t))alias.value=row;}catch(e){failed(t,e);}finally{if(current(t))loading.value=false;}}
watch([()=>store.state.user.accessToken,()=>JSON.stringify(roles.value),()=>props.poolId,()=>props.legacyScheduleId],()=>{participant.value=null;resourceId.value=null;aliasId.value=null;initialize();},{flush:'sync',immediate:true});
watch(participant,()=>{resourceId.value=null;aliasId.value=null;doctors.value=[];invalidate();},{flush:'sync'});watch(resourceId,()=>{aliasId.value=null;inspectResource();},{flush:'sync'});watch(aliasId,inspectAlias,{flush:'sync'});
watch(binding,()=>emit('validity',{valid:false,request:null}),{flush:'sync'});
onActivated(()=>{if(wasDeactivated){wasDeactivated=false;initialize();}});onDeactivated(()=>{wasDeactivated=true;clear();});onBeforeUnmount(()=>{alive=false;clear();});
</script>
<style scoped>p{line-height:1.7;overflow-wrap:anywhere}.el-select{width:100%}.el-checkbox{height:auto;white-space:normal}</style>
